# owner: platform
import unittest

from tests.support import data_file
from hourglass.timesheet import (
    format_hours,
    timesheet_lines,
)
from hourglass.schedule import load_schedule
from hourglass.models import Shift, Span

def make_shift(worker: str, start: int, stop: int) -> Shift:
    span = Span(start, stop)
    return Shift(worker, "mon", span)

class HoursTests(unittest.TestCase):
    def test_one_decimal_place(self):
        self.assertEqual(format_hours(0), "0.0")
        self.assertEqual(format_hours(540), "9.0")
        self.assertEqual(format_hours(65), "1.1")

    def test_halves_round_up(self):
        self.assertEqual(format_hours(75), "1.3")

class TimesheetLineTests(unittest.TestCase):
    def test_busiest_first_from_schedule(self):
        shifts = load_schedule(data_file("schedule.csv"))
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 3 shifts, 9.0 hours",
                "Quill: 2 shifts, 7.5 hours",
                "Odell: 2 shifts, 6.5 hours",
            ],
        )

    def test_ties_sorted_by_name(self):
        shifts = [
            make_shift("Zed", 480, 540),
            make_shift("Amy", 600, 660),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Amy: 1 shift, 1.0 hours",
                "Zed: 1 shift, 1.0 hours",
            ],
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.subTest(name=name):
                shifts = [make_shift(name, 480, 540)]
                with self.assertRaises(ValueError):
                    timesheet_lines(shifts)
